import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  EventEmitter,
  HostBinding,
  HostListener,
  Input,
  Output,
  ViewEncapsulation,
  booleanAttribute,
  inject,
} from '@angular/core';
import { ENTER, SPACE } from '@questrade/allspark-angular-components/core/utils';
import { QTabControl } from './tab-control';

@Component({
  selector: 'q-tab',
  template: '<ng-content />',
  styleUrls: ['./tab.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  providers: [{ provide: QTabControl, useExisting: QTabComponent }],
})
export class QTabComponent<T> implements QTabControl<T> {
  @Output() readonly tabClick = new EventEmitter<MouseEvent | KeyboardEvent>();
  @Output() readonly tabFocus = new EventEmitter<QTabControl<T>>();

  @Input() key!: T;
  @Input({ transform: booleanAttribute }) @HostBinding('class.q-tab-disabled') disabled = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-tab';

  @Input()
  @HostBinding('attr.aria-controls')
  ariaControls: string | null = null;

  @Input({ transform: booleanAttribute })
  @HostBinding('class.q-tab-selected')
  @HostBinding('attr.aria-selected')
  isActive = false;

  @HostBinding('class') hostClass = 'q-tab';
  @HostBinding('class.pressed') _pressed = false;
  @HostBinding('attr.role') role = 'tab';
  @HostBinding('attr.tabindex') get tabindexAttr(): number {
    return !this.disabled && this.isActive ? 0 : -1;
  }

  @HostListener('click', ['$event']) _onClick(event: MouseEvent): void {
    if (this.disabled) return;

    this.tabClick.emit(event);
  }

  @HostListener('keyup', ['$event']) _onTabKeyUp(event: KeyboardEvent): void {
    if (this.disabled || this.isActive) return;
    if (event.code === ENTER || event.code === SPACE) {
      this._pressed = this._pressed && false;
      this.tabClick.emit(event);
      event.preventDefault();
    }
  }

  @HostListener('keydown', ['$event']) _onTabIndexEnter(event: KeyboardEvent): void {
    if (this.disabled) return;

    if (event.code === ENTER || event.code === SPACE) {
      this._pressed = !this.isActive;
      event.preventDefault();
    }
  }

  @HostListener('focus', ['$event']) _onTabFocus(): void {
    if (this.disabled || this.isActive) return;

    this.tabFocus.emit(this);
  }

  translateValue = '0px';

  private readonly _elementRef = inject(ElementRef);
  private readonly _changeDetectorRef = inject(ChangeDetectorRef);

  getKey(): T {
    return this.key;
  }

  getIsActive(): boolean {
    return this.isActive;
  }

  /** @hidden */
  focus(): void {
    this._elementRef.nativeElement.focus();
    setTimeout(() => this.scrollTabIntoView('smooth'), 100);
  }

  scrollTabIntoView(behavior: ScrollBehavior): void {
    const tabsContainer = this._elementRef.nativeElement.closest('.q-tabs-items') as HTMLElement;
    const element = this._elementRef.nativeElement;
    const elementRect = element.getBoundingClientRect();
    const containerRect = tabsContainer.getBoundingClientRect();

    const elementCenter = elementRect.left + elementRect.width / 2;
    const containerCenter = containerRect.left + containerRect.width / 2;
    const scrollLeft = tabsContainer.scrollLeft + elementCenter - containerCenter;

    if (behavior === 'smooth') {
      tabsContainer.scrollTo({
        left: scrollLeft,
        behavior: 'smooth',
      });
    } else {
      tabsContainer.scrollLeft = scrollLeft;
    }
  }

  setActiveState(isActive: boolean): void {
    if (isActive !== this.isActive) {
      this.isActive = isActive;
      this.translateValue = isActive ? `${this.getElementWidth()}px` : '0px';
      this._changeDetectorRef.markForCheck();
    }
  }

  getElementWidth(): number {
    return parseInt(getComputedStyle(this._elementRef.nativeElement).width);
  }

  getElementLeft(): number {
    return (this._elementRef.nativeElement as HTMLElement).offsetLeft;
  }
}
